new = '''pub(super) fn emit_closed_stream_type_error(ctx: &mut FunctionContext<'_>, function_name: &str) {
    let message = if function_name == "stream_filter_remove" {
        "stream_filter_remove(): supplied resource is not a valid stream filter resource".to_string()
    } else {
        format!(
            "{}(): Argument #1 ($stream) must be an open stream resource",
            function_name
        )
    };
    // The shared emitter, not a second copy of it. This used to hand-roll the same allocation,
    // class id, message pair, code and `__rt_throw_current` jump — and the one thing it left out
    // was the creation line, so php reported `in FILE:LINE` for this TypeError and elephc reported
    // nothing. A duplicate of the throw machinery could only ever drift from it.
    super::super::exceptions::emit_type_error(ctx, &message);
}

'''
p.write_text(t[:start] + new + t[end:])
print('resource_handles.rs: routed through the shared TypeError emitter')
